using Hash = std::array<uint8_t, 32>;
struct Matrix { int d=0; std::vector<float>x; size_t rows()const{return d?x.size()/d:0;}const float*operator[](size_t i)const{return x.data()+i*d;} };
static Matrix fvecs(const std::string&p,size_t lim=0){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("cannot open "+p);Matrix a;while(!lim||a.rows()<lim){int32_t d;if(!f.read((char*)&d,4))break;if(a.d&&a.d!=d)throw std::runtime_error("bad fvecs");a.d=d;size_t o=a.x.size();a.x.resize(o+d);if(!f.read((char*)a.x.data()+o*4,4LL*d))throw std::runtime_error("truncated fvecs");}return a;}
static float l2(const float*a,const float*b,int d){float s=0;for(int j=0;j<d;++j){float v=a[j]-b[j];s+=v*v;}return s;}
static Hash sha(const void*p,size_t n){Hash h;SHA256(static_cast<const unsigned char*>(p),n,h.data());return h;}
static Hash pair_hash(const Hash&a,const Hash&b){uint8_t x[64];std::memcpy(x,a.data(),32);std::memcpy(x+32,b.data(),32);return sha(x,64);}
static Hash merkle(std::vector<Hash> v){if(v.empty())return sha(nullptr,0);size_t n=1;while(n<v.size())n*=2;v.resize(n,v.back());while(v.size()>1){std::vector<Hash>w(v.size()/2);for(size_t i=0;i<w.size();++i)w[i]=pair_hash(v[2*i],v[2*i+1]);v.swap(w);}return v[0];}

struct Config{std::string data="../dataset/sift",assign="../populated_index/PriorMax_SIFT1M_C100_clusterid.tsv",out="block_auth_results.csv";int nlist=100,k=100,nq=50;std::vector<int>probes{1,2,4,8,16,32,64,100},blocks{64,128,256,512,1024};};
static std::vector<int>nums(const std::string&s){std::vector<int>v;size_t p=0;while(p<s.size()){size_t q=s.find(',',p);v.push_back(std::stoi(s.substr(p,q-p)));if(q==std::string::npos)break;p=q+1;}return v;}
static Config parse(int ac,char**av){Config c;for(int i=1;i<ac;++i){std::string a=av[i];auto v=[&](){if(++i==ac)throw std::runtime_error("missing value");return std::string(av[i]);};if(a=="--dataset")c.data=v();else if(a=="--assignments")c.assign=v();else if(a=="--output")c.out=v();else if(a=="--queries")c.nq=std::stoi(v());else if(a=="--k")c.k=std::stoi(v());else if(a=="--nprobes")c.probes=nums(v());else if(a=="--block-sizes")c.blocks=nums(v());else if(a=="--help"){std::cout<<"Usage: block_auth_experiment [--queries 50] [--k 100] [--block-sizes 64,128,256,512,1024]\n";std::exit(0);}else throw std::runtime_error("unknown option "+a);}return c;}
static std::vector<std::vector<int>>load_lists(const std::string&p,int nl,size_t n){std::ifstream f(p);if(!f)throw std::runtime_error("cannot open assignments");std::vector<std::vector<int>>ls(nl);long id,c;size_t z=0;while(f>>id>>c){if(id<0||(size_t)id>=n||c<0||c>=nl)throw std::runtime_error("bad assignment");ls[c].push_back(id);++z;}if(z!=n)throw std::runtime_error("assignment mismatch");return ls;}
static std::vector<std::vector<float>>centers(const Matrix&x,const std::vector<std::vector<int>>&ls){std::vector<std::vector<float>>c(ls.size(),std::vector<float>(x.d));for(size_t z=0;z<ls.size();++z){for(int id:ls[z])for(int j=0;j<x.d;++j)c[z][j]+=x[id][j];for(float&v:c[z])v/=ls[z].size();}return c;}

struct SQ4{int d;std::vector<float>lo,step,err;std::vector<uint8_t>code;explicit SQ4(const Matrix&x):d(x.d),lo(d,std::numeric_limits<float>::infinity()),step(d),err(x.rows()),code(x.rows()*d){std::vector<float>hi(d,-std::numeric_limits<float>::infinity());for(size_t i=0;i<x.rows();++i)for(int j=0;j<d;++j){lo[j]=std::min(lo[j],x[i][j]);hi[j]=std::max(hi[j],x[i][j]);}for(int j=0;j<d;++j)step[j]=(hi[j]-lo[j])/15;for(size_t i=0;i<x.rows();++i){float e=0;for(int j=0;j<d;++j){int c=step[j]?std::clamp((int)std::lround((x[i][j]-lo[j])/step[j]),0,15):0;code[i*d+j]=c;float v=x[i][j]-(lo[j]+c*step[j]);e+=v*v;}err[i]=std::nextafter(std::sqrt(e)*(1+1e-6f)+1e-5f,std::numeric_limits<float>::infinity());}}float lb(const float*q,size_t id)const{float s=0;for(int j=0;j<d;++j){float v=q[j]-(lo[j]+code[id*d+j]*step[j]);s+=v*v;}return std::max(0.0f,std::sqrt(s)-err[id]);}};

// Number of sibling hashes in a complete binary multiproof for selected leaves.
static size_t proof_count(size_t n,const std::vector<int>&sel){if(!n)return 0;size_t p=1;while(p<n)p*=2;std::vector<uint8_t>mark(p);for(int x:sel)if(x>=0&&(size_t)x<n)mark[x]=1;std::vector<int>pref(p+1);for(size_t i=0;i<p;++i)pref[i+1]=pref[i]+mark[i];auto rec=[&](auto&&self,size_t l,size_t r)->size_t{int cnt=pref[r]-pref[l];if(!cnt)return 1;if(r-l==1)return 0;size_t m=(l+r)/2;return self(self,l,m)+self(self,m,r);};return rec(rec,0,p);}
static void pack_record(std::vector<uint8_t>&buf,int id,const SQ4&q){size_t o=buf.size();buf.resize(o+72);std::memcpy(buf.data()+o,&id,4);for(int j=0;j<q.d;j+=2)buf[o+4+j/2]=(q.code[(size_t)id*q.d+j]&15)|(q.code[(size_t)id*q.d+j+1]<<4);std::memcpy(buf.data()+o+68,&q.err[id],4);}

int main(int ac,char**av)try{Config cfg=parse(ac,av);std::cerr<<"Loading data and building per-object SQ4 certificates...\n";Matrix xb=fvecs(cfg.data+"/sift_base.fvecs"),xq=fvecs(cfg.data+"/sift_query.fvecs",cfg.nq);auto ls=load_lists(cfg.assign,cfg.nlist,xb.rows());auto cs=centers(xb,ls);SQ4 sq(xb);
// Build real SHA-256 block/cluster/global commitments for every block size and test binding.
std::cerr<<"Hashing exact vectors once for block subtrees...\n";std::vector<Hash>exact_hash(xb.rows());std::vector<uint8_t>exact_buf(4+xb.d*4);for(size_t i=0;i<xb.rows();++i){int id=i;std::memcpy(exact_buf.data(),&id,4);std::memcpy(exact_buf.data()+4,xb[i],xb.d*4);exact_hash[i]=sha(exact_buf.data(),exact_buf.size());}
for(int bs:cfg.blocks){std::vector<Hash>cluster_roots;for(size_t ci=0;ci<ls.size();++ci){const auto&list=ls[ci];std::vector<Hash>leaves;for(size_t b=0;b<list.size();b+=bs){size_t end=std::min(list.size(),b+bs);std::vector<uint8_t>buf;buf.reserve((end-b)*72);std::vector<Hash>eh;eh.reserve(end-b);for(size_t p=b;p<end;++p){pack_record(buf,list[p],sq);eh.push_back(exact_hash[list[p]]);}Hash quant_root=sha(buf.data(),buf.size()),exact_root=merkle(eh);uint8_t leaf[76];std::memcpy(leaf,quant_root.data(),32);std::memcpy(leaf+32,exact_root.data(),32);uint32_t meta[3]={(uint32_t)ci,(uint32_t)(b/bs),(uint32_t)(end-b)};std::memcpy(leaf+64,meta,12);leaves.push_back(sha(leaf,76));}cluster_roots.push_back(merkle(leaves));}Hash root=merkle(cluster_roots);auto altered=cluster_roots;altered[0][0]^=1;if(merkle(altered)==root)throw std::runtime_error("tamper self-test failed");std::cerr<<"SHA-256 quant+exact commitment verified, block="<<bs<<", global_root=";for(int i=0;i<6;++i)std::cerr<<std::hex<<std::setw(2)<<std::setfill('0')<<(int)root[i];std::cerr<<std::dec<<std::setfill(' ')<<"...\n";}
std::ofstream out(cfg.out);out<<"k,nprobe,block_size,avg_visited,avg_exact_open,quant_filter_ratio,record_payload_bytes,exact_payload_bytes,block_auth_bytes,naive_object_auth_bytes,total_block_vo_bytes,total_naive_vo_bytes,batch_auth_reduction,total_vo_reduction_vs_raw\n";std::cout<<"nprobe block visited exact block_auth naive_auth auth_reduction total_reduction\n";
for(int np:cfg.probes){uint64_t vis=0,exact=0;std::vector<double>auth(cfg.blocks.size());for(size_t qi=0;qi<xq.rows();++qi){std::vector<int>pr(cfg.nlist);std::iota(pr.begin(),pr.end(),0);std::partial_sort(pr.begin(),pr.begin()+np,pr.end(),[&](int a,int b){return l2(xq[qi],cs[a].data(),xb.d)<l2(xq[qi],cs[b].data(),xb.d);});using P=std::pair<float,int>;std::priority_queue<P>top;for(int u=0;u<np;++u)for(int id:ls[pr[u]]){float d=l2(xq[qi],xb[id],xb.d);++vis;if((int)top.size()<cfg.k)top.push({d,id});else if(d<top.top().first){top.pop();top.push({d,id});}}float tau=std::sqrt(top.top().first);std::vector<std::vector<int>>opened(np);for(int u=0;u<np;++u)for(size_t p=0;p<ls[pr[u]].size();++p)if(sq.lb(xq[qi],ls[pr[u]][p])<=tau){opened[u].push_back(p);++exact;}std::vector<int>selected(pr.begin(),pr.begin()+np);size_t global=proof_count(cfg.nlist,selected)*32;
for(size_t z=0;z<cfg.blocks.size();++z){int bs=cfg.blocks[z];double bytes=global;for(int u=0;u<np;++u){size_t nb=(ls[pr[u]].size()+bs-1)/bs;bytes+=nb*8;std::vector<std::vector<int>>local(nb);for(int p:opened[u])local[p/bs].push_back(p%bs);for(size_t b=0;b<nb;++b){size_t count=std::min<size_t>(bs,ls[pr[u]].size()-b*bs);bytes+=proof_count(count,local[b])*32;}}auth[z]+=bytes;}}
for(size_t z=0;z<cfg.blocks.size();++z){double record=vis*72.0,exact_bytes=exact*512.0,block=auth[z],naive=(vis-exact)*32.0;double total=record+exact_bytes+block,total_naive=record+exact_bytes+naive,raw=vis*(512.0+4);double ar=1-block/naive,tr=1-total/raw;out<<cfg.k<<','<<np<<','<<cfg.blocks[z]<<','<<(double)vis/xq.rows()<<','<<(double)exact/xq.rows()<<','<<1-(double)exact/vis<<','<<record/xq.rows()<<','<<exact_bytes/xq.rows()<<','<<block/xq.rows()<<','<<naive/xq.rows()<<','<<total/xq.rows()<<','<<total_naive/xq.rows()<<','<<ar<<','<<tr<<'\n';std::cout<<std::setw(6)<<np<<' '<<std::setw(5)<<cfg.blocks[z]<<' '<<std::fixed<<std::setprecision(1)<<vis/(double)xq.rows()<<' '<<exact/(double)xq.rows()<<' '<<block/xq.rows()<<' '<<naive/xq.rows()<<' '<<std::setprecision(4)<<ar<<' '<<tr<<'\n';}}
std::cerr<<"Wrote "<<cfg.out<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
